.sitzplan {
  overflow-x: auto;
}

.sitzplan__reihe {
  display: flex;
  gap: var(--spacing-seat-gap);
  margin-bottom: var(--spacing-seat-gap);
}

.sitzplan__reihen-label {
  position: sticky;
  left: 0;
  z-index: 1;
  flex: 0 0 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--color-surface);
  font-family: var(--font-label-family);
  font-size: var(--font-label-size);
  font-weight: var(--font-label-weight);
  line-height: var(--font-label-line-height);
  color: var(--color-on-surface-variant);
}

.sitzplan__luecke {
  flex: 0 0 32px;
  height: 32px;
}

.sitzplan__skeleton-kachel {
  flex: 0 0 32px;
  height: 32px;
  border-radius: var(--radius-sm);
  background: var(--color-surface-container-high);
}

.buchung__fehler {
  font-family: var(--font-body-lg-family);
  font-size: var(--font-body-lg-size);
  line-height: var(--font-body-lg-line-height);
  color: var(--color-on-error-container);
  background: var(--color-error-container);
  border-radius: var(--radius-default);
  padding: var(--spacing-gutter);
  margin: 0;
}

.sitzplatz-auswahl {
  margin-top: var(--spacing-section-gap);
}

.sitzplatz-auswahl__titel {
  font-family: var(--font-headline-sm-family);
  font-size: var(--font-headline-sm-size);
  font-weight: var(--font-headline-sm-weight);
  line-height: var(--font-headline-sm-line-height);
  color: var(--color-on-surface);
  margin: 0 0 var(--spacing-gutter);
}

.sitzplatz-auswahl__liste {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: var(--spacing-unit);
}

.sitzplatz-auswahl__zeile {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--spacing-unit);
}

.sitzplatz-auswahl__code {
  font-family: var(--font-body-md-family);
  font-size: var(--font-body-md-size);
  font-weight: 600;
  color: var(--color-on-surface);
  min-width: 40px;
}

.sitzplatz-auswahl__label {
  font-family: var(--font-label-family);
  font-size: var(--font-label-size);
  color: var(--color-on-surface-variant);
}

.sitzplatz-auswahl__select {
  font-family: var(--font-body-md-family);
  font-size: var(--font-body-md-size);
  color: var(--color-on-surface);
  background: var(--color-surface);
  border: 1px solid var(--color-outline);
  border-radius: var(--radius-sm);
  padding: var(--spacing-unit);
}

.sitzplatz-auswahl__select:focus-visible {
  outline: none;
  border-color: var(--color-primary);
}

.sitzplatz-auswahl__select--fehlt {
  border-color: var(--color-error);
}

.sitzplatz-auswahl__hinweis {
  font-family: var(--font-caption-family);
  font-size: var(--font-caption-size);
  color: var(--color-error);
}

.sitzplatz-auswahl__weiter {
  margin-top: var(--spacing-gutter);
  font-family: var(--font-body-md-family);
  font-size: var(--font-body-md-size);
  font-weight: 600;
  color: var(--color-on-primary);
  background: var(--color-primary);
  border: none;
  border-radius: var(--radius-default);
  padding: var(--spacing-unit) var(--spacing-gutter);
  cursor: pointer;
}

.sitzplatz-auswahl__weiter:disabled {
  background: var(--color-surface-container-highest);
  color: var(--color-on-surface-variant);
  cursor: not-allowed;
}

