    expect(seatDiv(fixture, 'A1').classList.contains('seat-tile--ausgewaehlt')).toBe(true);
  });

  it('bewegt den Fokus bei ArrowDown/ArrowUp eine Reihe weiter bzw. zurück bei gleichem Spalten-Index', () => {
